232			t.Fatal("冲突请求不得消除缺口")
233		}
234		if len(e.Records()) != recsBase {
235			t.Fatalf("等待重放与内容冲突都不得新增事件记录: 基础 %d，现有 %d",
236				recsBase, len(e.Records()))
237		}
238	
239		// 补齐 seq2：必须按最初等待的 (时刻30,价格20) 推进，而不是任一冲突数据。
240		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 20, Price: 10})
241		if err != nil || n != 2 {
242			t.Fatalf("补齐应使 seq2/seq3 依次生效: n=%d err=%v", n, err)
243		}
244		q, ok = e.CurrentQuote("A")
245		if !ok || q != (Quote{Seq: 3, Moment: 30, Price: 20}) {
246			t.Fatalf("补齐后必须保留最初等待的 seq3（时刻30,价格20）: %+v ok=%v", q, ok)
247		}
248		if e.HasGap("A") {
249			t.Fatal("补齐后缺口必须消失")
250		}
251	}
