type Quote struct {
	Seq    int64
	Moment int64
	Price  int64
}

// Order 是一笔已被接受的委托。
type Order struct {
	ID     int64
	Symbol string
	Side   Side
	Limit  int64 // 限价（正整数）
	Qty    int64 // 原始委托数量
	Filled int64 // 已成交数量
	Status OrderStatus
